#include <iostream>
#include <vector>
using namespace std;

using ll = long long;

const ll MOD = 1000000007LL;

ll modPow(ll base, ll exponent) {
    ll result = 1;
    while (exponent > 0) {
        if (exponent & 1) result = result * base % MOD;
        base = base * base % MOD;
        exponent >>= 1;
    }
    return result;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int zeroes, ones, g;
    cin >> zeroes >> ones >> g;

    if (zeroes == 0) {
        int result = (ones == 1 ? 1 : 0);
        cout << (result == g ? 1 : 0);
        return 0;
    }

    if (ones == 0) {
        int result = (zeroes % 2 == 0 ? 1 : 0);
        cout << (result == g ? 1 : 0);
        return 0;
    }

    int n = zeroes + ones;
    vector<ll> factorial(n + 1), inverseFactorial(n + 1);

    factorial[0] = 1;
    for (int i = 1; i <= n; ++i)
        factorial[i] = factorial[i - 1] * i % MOD;

    inverseFactorial[n] = modPow(factorial[n], MOD - 2);
    for (int i = n; i > 0; --i)
        inverseFactorial[i - 1] = inverseFactorial[i] * i % MOD;

    auto combinations = [&](int total, int chosen) -> ll {
        if (chosen < 0 || chosen > total) return 0;
        return factorial[total] * inverseFactorial[chosen] % MOD
             * inverseFactorial[total - chosen] % MOD;
    };

    ll answer = 0;

    for (int position = 1; position <= n; ++position) {
        int remainingZeroes = zeroes - (position - 1);
        if (remainingZeroes < 0) continue;

        int last = (position == n ? 1 : 0);
        int result = ((position - 1) % 2 == 0 ? last : 1 - last);

        if (result == g) {
            answer += combinations(n - position, remainingZeroes);
            if (answer >= MOD) answer -= MOD;
        }
    }

    cout << answer;
    return 0;
}

